```javascript
class NeuralNetwork {
  constructor(inputSize, hiddenSize, outputSize, learningRate = 0.1) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;
    this.learningRate = learningRate;

    // Initialize weights with small random values
    this.weightsInputHidden = this.randomMatrix(this.inputSize, this.hiddenSize);
    this.weightsHiddenOutput = this.randomMatrix(this.hiddenSize, this.outputSize);

    // Initialize biases
    this.biasHidden = this.randomArray(this.hiddenSize);
    this.biasOutput = this.randomArray(this.outputSize);
  }

  // Utility to create a matrix filled with random values
  randomMatrix(rows, cols) {
    const matrix = [];
    for (let i = 0; i < rows; i++) {
      const row = [];
      for (let j = 0; j < cols; j++) {
        row.push(Math.random() * 0.2 - 0.1); // small random values between -0.1 and 0.1
      }
      matrix.push(row);
    }
    return matrix;
  }

  // Utility to create an array filled with random values
  randomArray(size) {
    const arr = [];
    for (let i = 0; i < size; i++) {
      arr.push(Math.random() * 0.2 - 0.1);
    }
    return arr;
  }

  // Activation function (sigmoid)
  sigmoid(x) {
    return 1 / (1 + Math.exp(-x));
  }

  // Derivative of sigmoid
  sigmoidDerivative(x) {
    return x * (1 - x);
  }

  // Forward pass
  predict(inputArray) {
    // Input to hidden layer
    this.input = inputArray;
    this.hidden = this.matrixVectorMultiply(this.weightsInputHidden, inputArray);
    this.hidden = this.hidden.map((val, idx) => val + this.biasHidden[idx]);
    this.hiddenActivated = this.hidden.map(this.sigmoid);

    // Hidden to output layer
    this.output = this.matrixVectorMultiply(this.weightsHiddenOutput, this.hiddenActivated);
    this.output = this.output.map((val, idx) => val + this.biasOutput[idx]);
    this.outputActivated = this.output.map(this.sigmoid);

    return this.outputActivated;
  }

  // Train the network with one sample
  train(inputArray, targetArray) {
    // Forward pass
    this.predict(inputArray);

    // Calculate output errors (target - output)
    const outputErrors = targetArray.map((target, idx) => target - this.outputActivated[idx]);

    // Calculate delta for output layer
    const deltaOutput = this.outputActivated.map((outputVal, idx) => outputErrors[idx] * this.sigmoidDerivative(outputVal));

    // Calculate errors for hidden layer
    const weightsHiddenOutputT = this.transpose(this.weightsHiddenOutput);
    const hiddenErrors = this.matrixVectorMultiply(weightsHiddenOutputT, deltaOutput);

    // Calculate delta for hidden layer
    const deltaHidden = this.hiddenActivated.map((hiddenVal, idx) => hiddenErrors[idx] * this.sigmoidDerivative(hiddenVal));

    // Update weights between hidden and output layers
    for (let i = 0; i < this.weightsHiddenOutput.length; i++) {
      for (let j = 0; j < this.weightsHiddenOutput[0].length; j++) {
        this.weightsHiddenOutput[i][j] += this.learningRate * deltaOutput[j] * this.hiddenActivated[i];
      }
    }

    // Update biases for output layer
    for (let i = 0; i < this.biasOutput.length; i++) {
      this.biasOutput[i] += this.learningRate * deltaOutput[i];
    }

    // Update weights between input and hidden layers
    for (let i = 0; i < this.weightsInputHidden.length; i++) {
      for (let j = 0; j < this.weightsInputHidden[0].length; j++) {
        this.weightsInputHidden[i][j] += this.learningRate * deltaHidden[j] * this.input[i];
      }
    }

    // Update biases for hidden layer
    for (let i = 0; i < this.biasHidden.length; i++) {
      this.biasHidden[i] += this.learningRate * deltaHidden[i];
    }
  }

  // Utility: multiply matrix and vector
  matrixVectorMultiply(matrix, vector) {
    const result = [];
    for (let i = 0; i < matrix[0].length; i++) {
      let sum = 0;
      for (let j = 0; j < matrix.length; j++) {
        sum += matrix[j][i] * vector[j];
      }
      result.push(sum);
    }
    return result;
  }

  // Utility: transpose a matrix
  transpose(matrix) {
    const transposed = [];
    for (let i = 0; i < matrix[0].length; i++) {
      transposed[i] = [];
      for (let j = 0; j < matrix.length; j++) {
        transposed[i][j] = matrix[j][i];
      }
    }
    return transposed;
  }
}

// Example usage:
const nn = new NeuralNetwork(2, 3, 1, 0.5);

// Training data for XOR problem
const trainingData = [
  { input: [0, 0], target: [0] },
  { input: [0, 1], target: [1] },
  { input: [1, 0], target: [1] },
  { input: [1, 1], target: [0] },
];

// Training loop
for (let epoch = 0; epoch < 10000; epoch++) {
  for (const data of trainingData) {
    nn.train(data.input, data.target);
  }
}

// Testing
